require_once __DIR__.'/Life.php';Life::uid();if(!Life::admin()){http_response_code(403);exit;}
$db=Life::db();Life::install($db);$h=[Life::class,'h'];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){Life::check();try{$a=$_POST['action']??'';
if($a==='settings'){$disabled=array_values(array_diff(array_merge(array_keys(Life::TYPES),['ideas']),array_intersect(array_merge(array_keys(Life::TYPES),['ideas']),(array)($_POST['enabled']??[]))));$db->prepare('INSERT INTO finea_life_settings(id,games,disabled_json) VALUES(1,?,?) ON DUPLICATE KEY UPDATE games=VALUES(games),disabled_json=VALUES(disabled_json)')->execute([!empty($_POST['games']),json_encode($disabled)]);}
elseif($a==='save'){$kind=(string)($_POST['kind']??'');$title=trim((string)($_POST['title']??''));$body=trim((string)($_POST['body']??''));$date=$_POST['event_date']??'';$id=(int)($_POST['id']??0);if(!isset(Life::TYPES[$kind])||!$title||mb_strlen($title)>190||mb_strlen($body)>10000||($date!==''&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date)||!checkdate((int)substr($date,5,2),(int)substr($date,8,2),(int)substr($date,0,4)))))throw new InvalidArgumentException('Contenu invalide.');
$options=array_values(array_filter(array_map('trim',preg_split('/\R/u',(string)($_POST['options']??''))),static fn($v)=>$v!==''));if($kind==='poll'&&(count($options)<2||count($options)>10||strlen(implode('',$options))>2000))throw new InvalidArgumentException('Saisissez 2 à 10 réponses.');
$image=null;$mime=null;$f=$_FILES['image']??[];if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){if($f['error']!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name'])||$f['size']>3*1024*1024)throw new InvalidArgumentException('Image : 3 Mo maximum.');$info=@getimagesize($f['tmp_name']);if(!$info||!in_array($info['mime'],['image/jpeg','image/png','image/webp'],true)||$info[0]*$info[1]>20000000)throw new InvalidArgumentException('Image invalide.');$image=file_get_contents($f['tmp_name']);$mime=$info['mime'];}
$args=[$kind,$title,$body,$date?:null,json_encode($options),!empty($_POST['published'])];if($id){$q=$db->prepare('SELECT kind,options_json FROM finea_life_posts WHERE id=?');$q->execute([$id]);$old=$q->fetch(PDO::FETCH_ASSOC);if(!$old)throw new InvalidArgumentException('Publication inconnue.');if($old['kind']==='poll'||$kind==='poll')throw new InvalidArgumentException('Créez un nouveau sondage pour modifier ses questions.');$db->prepare('UPDATE finea_life_posts SET kind=?,title=?,body=?,event_date=?,options_json=?,published=?,image=COALESCE(?,image),mime=COALESCE(?,mime) WHERE id=?')->execute([...$args,$image,$mime,$id]);}else{$db->prepare('INSERT INTO finea_life_posts(kind,title,body,event_date,options_json,published,image,mime) VALUES(?,?,?,?,?,?,?,?)')->execute([...$args,$image,$mime]);}}
elseif($a==='toggle'){$db->prepare('UPDATE finea_life_posts SET published=1-published WHERE id=?')->execute([(int)$_POST['id']]);}
elseif($a==='idea_status'){$status=$_POST['status']??'';if(!in_array($status,['new','reviewed','closed'],true))throw new InvalidArgumentException('Statut invalide.');$db->prepare('UPDATE finea_life_ideas SET status=? WHERE id=?')->execute([$status,(int)$_POST['id']]);}
else throw new InvalidArgumentException('Action inconnue.');
header('Location: admin.php');exit;}catch(InvalidArgumentException $e){$error=$e->getMessage();}}
