<section class="life-card"><h2><?=$edit?'Modifier':'Nouvelle publication'?></h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=Life::csrf()?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><label>Rubrique<select name="kind"><?php foreach(Life::TYPES as $key=>$label):?><option value="<?=$key?>" <?=($edit['kind']??'')===$key?'selected':''?>><?=$h($label)?></option><?php endforeach;?></select></label><label>Titre<input name="title" required maxlength="190" value="<?=$h($edit['title']??'')?>"></label><label>Description<textarea name="body" maxlength="10000"><?=$h($edit['body']??'')?></textarea></label><label>Date facultative<input type="date" name="event_date" value="<?=$h($edit['event_date']??'')?>"></label><label>Image facultative<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><label>Réponses (sondage uniquement, une par ligne)<textarea name="options"></textarea></label><label><input type="checkbox" name="published" value="1" <?=!empty($edit['published'])?'checked':''?>> Publier</label><button name="action" value="save">Enregistrer</button></form></section>
<section><h2>Publications</h2><?php foreach($posts as $p):?><article class="life-card"><strong><?=$h($p['title'])?></strong> · <?=$p['published']?'Publié':'Brouillon'?><?php if($p['kind']!=='poll'):?> · <a href="?edit=<?=(int)$p['id']?>">Modifier</a><?php else:$q=$db->prepare('SELECT choice,COUNT(*) AS total FROM finea_life_votes WHERE post_id=? GROUP BY choice');$q->execute([$p['id']]);$counts=$q->fetchAll(PDO::FETCH_KEY_PAIR);foreach(json_decode($p['options_json'],true) as $n=>$option):?><p><?=$h($option)?> : <?=(int)($counts[$n]??0)?> vote(s)</p><?php endforeach;endif;?><form method="post"><input type="hidden" name="csrf" value="<?=Life::csrf()?>"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button name="action" value="toggle"><?=$p['published']?'Retirer':'Publier'?></button></form></article><?php endforeach;?></section><section><h2>Suggestions reçues</h2><?php foreach($ideas as $idea):?><article class="life-card"><small>Collaborateur #<?=(int)$idea['user_id']?> · <?=$h($idea['created_at'])?></small><p><?=nl2br($h($idea['body']))?></p><form method="post"><input type="hidden" name="csrf" value="<?=Life::csrf()?>"><input type="hidden" name="id" value="<?=(int)$idea['id']?>"><select name="status"><?php foreach(['new'=>'Nouvelle','reviewed'=>'Examinée','closed'=>'Traitée'] as $v=>$label):?><option value="<?=$v?>" <?=$idea['status']===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select><button name="action" value="idea_status">Mettre à jour</button></form></article><?php endforeach;?></section></main><?php require __DIR__.'/../decaissement/includes/footer.php';?>
